import os.path
import six
from abc import ABCMeta, abstractmethod
from future.utils import with_metaclass
from taf.ul.ettf.utils.exception import LibraryError
from taf.ul.ettf.utils import exception_causes
from collections import namedtuple, OrderedDict

WrappedData = namedtuple('WrappedData', ['func', 'args', 'kwargs'])


if six.PY3:
    unicode = str


class InvalidThroughputValue(LibraryError):
    pass


class InvalidMarginValue(LibraryError):
    pass


class InvalidIp(LibraryError):
    pass


class CustomType(with_metaclass(ABCMeta, object)):
    @property
    def wrapped_data(self):
        return self._wrapped_data

    @wrapped_data.setter
    def wrapped_data(self, data):
        self._wrapped_data = data

    @abstractmethod
    def assert_type(self, value):
        pass

    @abstractmethod
    def __call__(self, argument):
        pass


class BaseType(CustomType):
    def __init__(self, type_converter):
        self.type_converter = type_converter

    def assert_type(self, value):
        assert isinstance(value, self.type_converter)

    def __call__(self, argument):
        return self.type_converter(argument)


class NotIterableException(LibraryError):
    def __init__(self, msg):
        super(NotIterableException, self).__init__(exception_causes.INVALID_INPUT, msg)


class List(CustomType):
    def __init__(self, type_def):
        self.type_def = type_def

    def __call__(self, iterable):
        try:
            return [self.type_def(i) for i in iterable]
        except Exception as e:
            raise NotIterableException(e)

    def assert_type(self, value):
        for elem in value:
            assert isinstance(elem, self.type_def)


class Filepath(CustomType):
    def __init__(self):
        self.type_def = str

    def __call__(self, arg):
        filepath = os.path.normpath(self.type_def(arg))
        return filepath

    def assert_type(self, value):
        assert isinstance(value, self.type_def)


class ExistingFilepath(CustomType):
    def __init__(self):
        self.type_def = str

    def __call__(self, arg):
        filepath = Filepath()(arg)
        self._assert_that_filepath_exists(filepath)
        return filepath

    def assert_type(self, value):
        assert isinstance(value, self.type_def)
        self._assert_that_filepath_exists(value)

    def _assert_that_filepath_exists(self, filepath):
        assert os.path.exists(filepath), 'Given filepath \'{}\' does not exist'.format(filepath)


class IsType(CustomType):
    def __init__(self, expected_type):
        self.expected_type = expected_type

    def assert_type(self, value):
        pass

    def __call__(self, argument):
        assert isinstance(argument, self.expected_type), 'Param type does not match. Expected: {}, got: {}'.format(self.expected_type, type(argument))
        return argument


class Bytes(CustomType):
    def __init__(self):
        self.type_def = bytes

    def assert_type(self, value):
        assert isinstance(value, self.type_def)

    def __call__(self, argument):
        if isinstance(argument, bytes):
            return argument
        return self.type_def(argument, 'utf-8')


class AnyOf(CustomType):
    def __init__(self, valid_values):
        assert isinstance(valid_values, list), 'valid_values ({}) should be a list'.format(valid_values)
        self.valid_values = valid_values

    def assert_type(self, value):
        pass

    def __call__(self, argument):
        assert argument in self.valid_values, '{} is not valid. Valid values={}'.format(argument, self.valid_values)
        return argument


class Ip(CustomType):
    def assert_type(self, value):
        pass

    def __call__(self, potential_ip):
        self._check_type(potential_ip)
        ip = self._check_format(potential_ip)
        self._check_values(ip)
        return potential_ip

    @staticmethod
    def _check_type(potential_ip):
        if not isinstance(potential_ip, str):
            raise InvalidIp('Invalid type',
                            'Ip should be passed as string')

    @staticmethod
    def _check_format(potential_ip):
        ip = potential_ip.split('.')
        if not len(ip) == 4:
            raise InvalidIp('Invalid format',
                            'Ip does not fit expected format: x.x.x.x {}'.format(ip))
        return ip

    @staticmethod
    def _check_values(ip):
        for p in ip:
            try:
                int(p)
            except ValueError:
                raise InvalidIp('Invalid value',
                                'At least one of the octets is not a decimal value')


class Margin(CustomType):
    def assert_type(self, value):
        pass

    def __call__(self, margin):
        expected_types = (str, unicode)
        try:
            if isinstance(margin, expected_types):
                return float(margin.replace('%', 'e-2'))
            return float(margin)
        except ValueError:
            raise InvalidMarginValue('Invalid margin value',
                                     'Should be floating point or string representing percentage e.g. \'42%\'')


class ThroughputValue(CustomType):
    units_map = OrderedDict([
        ('Kbps', 'e+3'),
        ('K', 'e+3'),
        ('Mbps', 'e+6'),
        ('M', 'e+6')
    ])

    def assert_type(self, value):
        pass

    def __call__(self, throughput):
        expected_types = (str, unicode)
        try:
            if not isinstance(throughput, expected_types):
                return float(throughput)

            for unit, float_counterpart in self.units_map.items():
                if unit in throughput:
                    return float(throughput.replace(' ', '').replace(unit, float_counterpart))

            return float(throughput)
        except ValueError:
            raise InvalidThroughputValue('Invalid value, need to be parsable to float',
                                         '{} markers are allowed'.format(self.units_map.keys()))


class ParsedRobotKeyword(object):
    def __init__(self, name, args):
        self._name = name
        self._args = args

    def name(self):
        return self._name

    def args(self):
        return self._args


class EmptyParameter(LibraryError):
    def __init__(self, msg):
        super(EmptyParameter, self).__init__('Empty parameter', msg)


class InvalidParameter(LibraryError):
    def __init__(self, msg):
        super(InvalidParameter, self).__init__('Invalid parameter', msg)


class RobotKeyword(CustomType):
    def assert_type(self, value):
        pass

    def __call__(self, keyword_with_args):
        expected_types = (str, unicode)
        assert isinstance(keyword_with_args, expected_types), 'Passed argument should be a string from robotframework: {}'.format(keyword_with_args)

        keyword_name = ''
        args = []
        words = [word for word in keyword_with_args.split(' ') if word]

        for word in words:
            if '=' not in word:
                keyword_name += ' ' + word
            else:
                try:
                    arg_name, arg_value = word.split('=')
                except ValueError:
                    raise InvalidParameter('Parameter should follow \'param_name=param_value\' convention')
                if not arg_name:
                    raise EmptyParameter('Parameter name should not be empty: {}'.format(word))
                if not arg_value:
                    raise EmptyParameter('Parameter value should not be empty: {}'.format(word))
                args.append(word)
        return ParsedRobotKeyword(keyword_name.strip(), args)
